-- ============================================
-- 城市资源一张图 开发环境种子数据
-- PostgreSQL + PostGIS
-- 说明：基于上海市嘉定区真实地理坐标模拟数据
-- ============================================

BEGIN;

-- ============================================
-- 1. 建筑数据（20 栋典型建筑）
-- ============================================

-- ============================================
-- 2. 道路数据（10 条主干道）
-- ============================================

-- ============================================
-- 3. 摄像头数据（30 个点位）
-- ============================================

-- ============================================
-- 4. 网格数据（8 个社区网格）
-- ============================================

-- ============================================
-- 5. 人口数据（50 条记录）
-- ============================================

-- ============================================
-- 6. 户数据（50 条）
-- ============================================

-- ============================================
-- 7. 企业数据（20 条）
-- ============================================

-- ============================================
-- 8. 井盖数据（15 个）
-- ============================================

-- ============================================
-- 9. 路灯数据（20 盏）
-- ============================================

-- ============================================
-- 10. 生态监测站数据（6 个站点）
-- ============================================

-- ============================================
-- 11. 消防栓数据（10 个）
-- ============================================

-- ============================================
-- 12. 安防岗点数据（6 个）
-- ============================================

-- ============================================
-- 13. 示例告警事件（10 条历史记录）
-- ============================================

-- ============================================
-- 14. 审计日志样本（20 条）
-- ============================================

-- ============================================
-- 15. 刷新物化视图
-- ============================================
REFRESH MATERIALIZED VIEW v_building_aggregation;

COMMIT;

-- ============================================
-- 验证数据
-- ============================================
SELECT '建筑' AS 表名, COUNT(*) AS 记录数 FROM buildings UNION ALL
SELECT '道路', COUNT(*) FROM roads UNION ALL
SELECT '摄像头', COUNT(*) FROM cameras UNION ALL
SELECT '网格', COUNT(*) FROM grids UNION ALL
SELECT '人口', COUNT(*) FROM populations UNION ALL
SELECT '户', COUNT(*) FROM households UNION ALL
SELECT '企业', COUNT(*) FROM enterprises UNION ALL
SELECT '井盖', COUNT(*) FROM manhole_covers UNION ALL
SELECT '路灯', COUNT(*) FROM street_lights UNION ALL
SELECT '生态监测站', COUNT(*) FROM ecology_stations UNION ALL
SELECT '消防栓', COUNT(*) FROM fire_hydrants UNION ALL
SELECT '安防岗点', COUNT(*) FROM police_stations UNION ALL
SELECT '告警事件', COUNT(*) FROM alert_events UNION ALL
SELECT '审计日志', COUNT(*) FROM audit_logs
ORDER BY 表名;
